import {
  CancellationTokenSource,
  Disposable,
  IList,
  ListContext,
  ListAction,
  ListItem,
  ListOptions,
  ListTask,
  commands,
  window,
  workspace,
} from "coc.nvim";
import * as path from "node:path";
import { getListSource } from "./list-source";
import { formatPickerItem } from "./item-display";
import {
  PREVIEW_MAX_BYTES,
  PREVIEW_MAX_LINES,
  previewStatusLines,
  readPreviewContent,
  resolvePreviewFiletype,
} from "./preview-content";
import {
  PREVIEW_MIN_COLUMNS,
  canShowPreviewPane,
  computePickerLayout,
  pickerLayoutsEqual,
  type PickerLayout,
} from "./preview-layout";
import {
  previewIdentity,
  resolvePreviewTarget,
} from "./preview-location";

type PreviewState = {
  buffer: number;
  window: number;
  path: string;
  /** Stable path+focus identity for the content currently painted. */
  identity: string;
  focusLine?: number;
};

type FloatState = {
  namespace: number;
  promptBuffer: number;
  promptWindow: number;
  resultsBuffer: number;
  resultsWindow: number;
  targetBuffer: number;
  targetMode: string;
  targetWindow: number;
  layout: PickerLayout;
  preview?: PreviewState;
};

type MatchedItem = {
  item: ListItem;
  positions?: Uint32Array;
  score: number;
};

const DEFAULT_LIMIT = 10_000;
const DEFAULT_VISIBLE_ITEMS = 200;
const POLL_INTERVAL = 35;
/** Below Neovim's default float zindex (50) so native Coc menus/dialogs stack above. */
const PICKER_ZINDEX = 40;

/**
 * Joined prompt/results float borders. Outer corners follow `dialog.rounded`;
 * shared separator junctions stay ├ ┤. Neovim order: TL, T, TR, R, BR, B, BL, L.
 */
function pickerBorders(rounded: boolean): {
  prompt: string[];
  results: string[];
  preview: string[];
} {
  const [topLeft, topRight, bottomRight, bottomLeft] = rounded
    ? (["╭", "╮", "╯", "╰"] as const)
    : (["┌", "┐", "┘", "└"] as const);
  return {
    prompt: [topLeft, "─", topRight, "│", "┤", "─", "├", "│"],
    results: ["├", "─", "┤", "│", bottomRight, "─", bottomLeft, "│"],
    preview: [topLeft, "─", topRight, "│", bottomRight, "─", bottomLeft, "│"],
  };
}

function floatConfig(
  geometry: { row: number; col: number; width: number; height: number },
  border: string[],
  extra: Record<string, unknown> = {},
): Record<string, unknown> {
  return {
    relative: "editor",
    row: geometry.row,
    col: geometry.col,
    width: geometry.width,
    height: geometry.height,
    style: "minimal",
    border,
    zindex: PICKER_ZINDEX,
    ...extra,
  };
}

export class ListPicker implements Disposable {
  private state: FloatState | undefined;
  private name: string | undefined;
  private source: IList | undefined;
  private args: string[] = [];
  private items: ListItem[] = [];
  private visibleItems: MatchedItem[] = [];
  private readonly fuzzyMatch = workspace.createFuzzyMatch();
  private selected = 0;
  private input = "";
  private generation = 0;
  private previewGeneration = 0;
  private previewTokenSource: CancellationTokenSource | undefined;
  private tokenSource: CancellationTokenSource | undefined;
  private task: ListTask | undefined;
  private pollTimer: NodeJS.Timeout | undefined;
  private renderTimer: NodeJS.Timeout | undefined;
  private filterTimer: NodeJS.Timeout | undefined;
  private limit = DEFAULT_LIMIT;
  private visibleLimit = DEFAULT_VISIBLE_ITEMS;
  private previewEnabled = true;
  private previewMinColumns = PREVIEW_MIN_COLUMNS;

  async show(name: string, args: string[] = []): Promise<void> {
    await this.open(name, args, "");
  }

  async resume(): Promise<void> {
    if (!this.name) return;
    await this.open(this.name, this.args, this.input);
  }

  private async open(
    name: string,
    args: string[],
    input: string,
  ): Promise<void> {
    await this.close();
    const config = workspace.getConfiguration("ui.picker");
    this.limit = Math.max(100, config.get<number>("maxItems", DEFAULT_LIMIT));
    this.visibleLimit = Math.max(
      20,
      config.get<number>("visibleItems", DEFAULT_VISIBLE_ITEMS),
    );
    this.previewEnabled = config.get<boolean>("preview.enable", true);
    this.previewMinColumns = Math.max(
      LAYOUT_MIN_COLUMNS_FLOOR,
      config.get<number>("preview.minColumns", PREVIEW_MIN_COLUMNS),
    );
    this.name = name;
    this.source = getListSource(name);
    this.args = [...args];
    this.input = input;
    this.state = await this.openWindows(name);
    await workspace.nvim.call("nvim_buf_set_lines", [
      this.state.promptBuffer,
      0,
      -1,
      false,
      [input],
    ]);
    this.installCommands();
    this.pollTimer = setInterval(() => void this.pollInput(), POLL_INTERVAL);
    await workspace.nvim.call("win_gotoid", [this.state.promptWindow]);
    await workspace.nvim.call("nvim_win_set_cursor", [
      this.state.promptWindow,
      [1, Buffer.byteLength(input)],
    ]);
    await workspace.nvim.command("startinsert");
    await this.reload();
  }

  async close(): Promise<void> {
    this.cancelProducer();
    this.previewGeneration++;
    this.previewTokenSource?.cancel();
    this.previewTokenSource?.dispose();
    this.previewTokenSource = undefined;
    if (this.pollTimer) clearInterval(this.pollTimer);
    if (this.renderTimer) clearTimeout(this.renderTimer);
    if (this.filterTimer) clearTimeout(this.filterTimer);
    this.pollTimer = undefined;
    this.renderTimer = undefined;
    this.filterTimer = undefined;
    const state = this.state;
    this.state = undefined;
    if (!state) return;
    await workspace.nvim.command("stopinsert");
    const windows = [
      state.promptWindow,
      state.resultsWindow,
      state.preview?.window,
    ].filter((winid): winid is number => winid != null);
    for (const winid of windows) {
      const valid = (await workspace.nvim.call("nvim_win_is_valid", [
        winid,
      ])) as boolean;
      if (valid) await workspace.nvim.call("nvim_win_close", [winid, true]);
    }
    if (state.preview) {
      const bufValid = (await workspace.nvim.call("nvim_buf_is_valid", [
        state.preview.buffer,
      ])) as boolean;
      if (bufValid) {
        await workspace.nvim.call("nvim_buf_delete", [
          state.preview.buffer,
          { force: true },
        ]);
      }
    }
    const targetValid = (await workspace.nvim.call("nvim_win_is_valid", [
      state.targetWindow,
    ])) as boolean;
    if (targetValid) {
      await workspace.nvim.call("win_gotoid", [state.targetWindow]);
      if (state.targetMode.startsWith("i")) {
        await workspace.nvim.command("startinsert");
      } else if (state.targetMode.startsWith("R")) {
        await workspace.nvim.command("startreplace");
      }
    }
  }

  dispose(): void {
    void this.close();
  }

  async move(delta: number): Promise<void> {
    if (!this.visibleItems.length) return;
    this.selected = Math.max(
      0,
      Math.min(this.visibleItems.length - 1, this.selected + delta),
    );
    await this.render();
  }

  async accept(): Promise<void> {
    const source = this.source;
    const item = this.visibleItems[this.selected]?.item;
    if (!source || !item) return;
    const action =
      source.actions.find((candidate) => candidate.name === source.defaultAction) ??
      source.actions[0];
    if (!action) return;
    await this.executeAction(action, item);
  }

  async showActions(): Promise<void> {
    const source = this.source;
    const item = this.visibleItems[this.selected]?.item;
    if (!source || !item || !source.actions.length) return;
    const index = await window.showMenuPicker(
      source.actions.map((action) => action.name),
      { title: "Actions" },
    );
    if (index < 0) {
      await this.focusPrompt();
      return;
    }
    const action = source.actions[index];
    if (!action) {
      await this.focusPrompt();
      return;
    }
    await this.executeAction(action, item);
    if (this.state) await this.focusPrompt();
  }

  private async focusPrompt(): Promise<void> {
    const state = this.state;
    if (!state) return;
    await workspace.nvim.call("win_gotoid", [state.promptWindow]);
    await workspace.nvim.call("nvim_win_set_cursor", [
      state.promptWindow,
      [1, Buffer.byteLength(this.input)],
    ]);
    await workspace.nvim.command("startinsert");
  }

  private async executeAction(
    action: ListAction,
    unresolvedItem: ListItem,
  ): Promise<void> {
    const source = this.source;
    if (!source) return;
    const item = source.resolveItem
      ? ((await source.resolveItem(unresolvedItem)) ?? unresolvedItem)
      : unresolvedItem;
    const context = this.context(this.input);
    if (!action.persist) await this.close();
    await action.execute(item, context);
    if (action.persist && action.reload && this.state) await this.reload();
  }

  private async reload(): Promise<void> {
    const source = this.source;
    if (!source || !this.state) return;
    this.cancelProducer();
    const generation = ++this.generation;
    const tokenSource = (this.tokenSource = new CancellationTokenSource());
    this.items = [];
    this.visibleItems = [];
    this.selected = 0;
    this.scheduleRender();

    const loaded = await source.loadItems(
      this.context(this.input),
      tokenSource.token,
    );
    if (generation !== this.generation || tokenSource.token.isCancellationRequested)
      return;
    if (!loaded) return;
    if (Array.isArray(loaded)) {
      for (const item of loaded.slice(0, this.limit)) this.push(item, generation);
      this.scheduleFilter();
      return;
    }
    const task = (this.task = loaded);
    task.on("data", (item) => this.push(item, generation));
    task.on("end", () => {
      if (generation === this.generation) this.task = undefined;
    });
    task.on("error", (error) => {
      if (generation !== this.generation) return;
      this.task = undefined;
      void this.close();
      void window.showErrorMessage(`Picker source failed: ${String(error)}`);
    });
  }

  private push(item: ListItem, generation: number): void {
    if (generation !== this.generation) return;
    if (this.items.length >= this.limit) {
      this.task?.dispose();
      this.task = undefined;
      return;
    }
    this.items.push(item);
    this.scheduleFilter();
  }

  private scheduleFilter(): void {
    if (this.filterTimer) return;
    this.filterTimer = setTimeout(() => {
      this.filterTimer = undefined;
      this.applyFilter();
    }, POLL_INTERVAL);
  }

  private applyFilter(): void {
    const query = this.input;
    let filtered: MatchedItem[];
    if (this.source?.interactive || query.length === 0) {
      filtered = this.items.map((item) => ({ item, score: 0 }));
    } else {
      this.fuzzyMatch.setPattern(query);
      filtered = this.items
        .map((item, index): (MatchedItem & { index: number }) | undefined => {
          const filterText = item.filterText ?? item.label;
          const result = this.fuzzyMatch.match(filterText);
          if (!result) return undefined;
          const labelResult =
            filterText === item.label ? result : this.fuzzyMatch.match(item.label);
          return {
            item,
            index,
            positions: labelResult?.positions,
            score: result.score,
          };
        })
        .filter(
          (item): item is MatchedItem & { index: number } => item != null,
        )
        .sort((left, right) => right.score - left.score || left.index - right.index);
    }
    this.visibleItems = filtered;
    this.selected = Math.min(this.selected, Math.max(0, filtered.length - 1));
    this.scheduleRender();
  }

  private cancelProducer(): void {
    this.generation++;
    this.tokenSource?.cancel();
    this.tokenSource?.dispose();
    this.tokenSource = undefined;
    this.task?.dispose();
    this.task = undefined;
  }

  private async pollInput(): Promise<void> {
    const state = this.state;
    if (!state) return;
    const valid = (await workspace.nvim.call("nvim_buf_is_valid", [
      state.promptBuffer,
    ])) as boolean;
    if (!valid) return void this.close();
    const lines = (await workspace.nvim.call("nvim_buf_get_lines", [
      state.promptBuffer,
      0,
      1,
      false,
    ])) as string[];
    const input = lines[0] ?? "";
    if (input === this.input) return;
    this.input = input;
    if (this.source?.interactive) await this.reload();
    else this.applyFilter();
  }

  private scheduleRender(): void {
    if (this.renderTimer) return;
    this.renderTimer = setTimeout(() => {
      this.renderTimer = undefined;
      void this.render();
    }, POLL_INTERVAL);
  }

  private async render(): Promise<void> {
    const state = this.state;
    if (!state) return;
    const half = Math.floor(this.visibleLimit / 2);
    const start = Math.max(
      0,
      Math.min(this.selected - half, this.visibleItems.length - this.visibleLimit),
    );
    const page = this.visibleItems.slice(start, start + this.visibleLimit);
    const displayItems = page.map(({ item, positions }) =>
      formatPickerItem(item.label, positions, state.layout.results.width),
    );
    const lines = displayItems.map(({ text }) => text);
    await workspace.nvim.pauseNotification();
    workspace.nvim.call("nvim_buf_set_option", [state.resultsBuffer, "modifiable", true], true);
    workspace.nvim.call("nvim_buf_set_lines", [state.resultsBuffer, 0, -1, false, lines.length ? lines : [""]], true);
    workspace.nvim.call("nvim_buf_set_option", [state.resultsBuffer, "modifiable", false], true);
    workspace.nvim.call("nvim_buf_clear_namespace", [state.resultsBuffer, state.namespace, 0, -1], true);
    if (page.length) {
      workspace.nvim.call("nvim_buf_add_highlight", [state.resultsBuffer, state.namespace, "PmenuSel", this.selected - start, 0, -1], true);
      for (const [line, displayed] of displayItems.entries()) {
        if (!displayed.positions) continue;
        for (const [startColumn, endColumn] of this.fuzzyMatch.matchSpans(
          lines[line],
          displayed.positions,
        )) {
          workspace.nvim.call("nvim_buf_add_highlight", [
            state.resultsBuffer,
            state.namespace,
            "CocListSearch",
            line,
            startColumn,
            endColumn,
          ], true);
        }
      }
    }
    await workspace.nvim.resumeNotification(false);
    if (page.length) {
      await this.revealResultsLine(this.selected - start + 1);
    }
    await this.updatePreview();
  }

  private async revealResultsLine(line: number): Promise<void> {
    const state = this.state;
    if (!state) return;
    await workspace.nvim.lua(
      `
      local win, line = ...
      if vim.api.nvim_win_is_valid(win) then
        vim.api.nvim_win_call(win, function()
          vim.api.nvim_win_set_cursor(win, { line, 0 })
          vim.cmd('normal! zz')
        end)
      end
      `,
      [state.resultsWindow, line],
    );
  }

  private async updatePreview(): Promise<void> {
    const state = this.state;
    if (!state) return;
    this.previewTokenSource?.cancel();
    this.previewTokenSource?.dispose();
    const previewTokenSource = new CancellationTokenSource();
    this.previewTokenSource = previewTokenSource;
    const generation = ++this.previewGeneration;
    const item = this.visibleItems[this.selected]?.item;
    const target = item
      ? resolvePreviewTarget(item.location, workspace.cwd)
      : undefined;
    const columns = (await workspace.nvim.getOption("columns")) as number;
    const lines = (await workspace.nvim.getOption("lines")) as number;
    if (generation !== this.previewGeneration || !this.state) return;

    const wideEnough =
      this.previewEnabled &&
      canShowPreviewPane(columns, this.previewMinColumns);
    if (!wideEnough || !target) {
      if (state.preview || state.layout.preview) {
        await this.hidePreview(columns, lines);
      }
      return;
    }

    const identity = previewIdentity(target);
    const layout = computePickerLayout({
      columns,
      lines,
      showPreview: true,
      minColumns: this.previewMinColumns,
    });
    // Same selection already painted: skip reread/repaint. Still reflow when
    // editor geometry or settings change the computed pane partition (outer
    // size stays fixed for a given editor size).
    if (state.preview?.identity === identity) {
      if (pickerLayoutsEqual(state.layout, layout)) return;
      await this.applyLayout(layout, target.path);
      if (generation !== this.previewGeneration || !this.state) return;
      return;
    }

    const content = await readPreviewContent(target.path, {
      maxBytes: PREVIEW_MAX_BYTES,
      maxLines: PREVIEW_MAX_LINES,
      cancellation: previewTokenSource.token,
      targetLine: target.line,
      matchLine: target.matchLine,
    });
    if (generation !== this.previewGeneration || !this.state) return;
    // Missing files, directories, and read errors are not previewable.
    if (content.kind === "unavailable") {
      if (this.state.preview || this.state.layout.preview) {
        await this.hidePreview(columns, lines);
      }
      return;
    }

    // Mount/partition before painting so the fixed outer rectangle stays put
    // while preview lines load.
    await this.applyLayout(layout, target.path);
    if (generation !== this.previewGeneration || !this.state?.preview) return;

    const focusLine =
      content.kind === "text" ? content.focusLine : undefined;
    const display = previewStatusLines(content);
    const detected =
      content.kind === "text" && !content.filetype
        ? await this.detectFiletype(target.path)
        : undefined;
    if (generation !== this.previewGeneration || !this.state?.preview) return;
    await this.writePreviewBuffer(
      this.state.preview.buffer,
      display,
      resolvePreviewFiletype(content, detected),
    );
    if (generation !== this.previewGeneration || !this.state?.preview) return;
    await this.focusPreviewLine(this.state.preview, focusLine, display.length);
    this.state.preview.path = target.path;
    this.state.preview.identity = identity;
    this.state.preview.focusLine = focusLine;
  }

  private async hidePreview(columns: number, lines: number): Promise<void> {
    const state = this.state;
    if (!state) return;
    if (state.preview) {
      const winValid = (await workspace.nvim.call("nvim_win_is_valid", [
        state.preview.window,
      ])) as boolean;
      if (winValid) {
        await workspace.nvim.call("nvim_win_close", [state.preview.window, true]);
      }
      const bufValid = (await workspace.nvim.call("nvim_buf_is_valid", [
        state.preview.buffer,
      ])) as boolean;
      if (bufValid) {
        await workspace.nvim.call("nvim_buf_delete", [
          state.preview.buffer,
          { force: true },
        ]);
      }
      state.preview = undefined;
    }
    // Give list/prompt the full outer rectangle; col/width of that outer box
    // match the preview-partitioned layout for this editor size.
    const layout = computePickerLayout({
      columns,
      lines,
      showPreview: false,
      minColumns: this.previewMinColumns,
    });
    await this.applyLayout(layout);
  }

  private async applyLayout(
    layout: PickerLayout,
    previewPath?: string,
  ): Promise<void> {
    const state = this.state;
    if (!state) return;
    const rounded = workspace
      .getConfiguration("dialog")
      .get<boolean>("rounded", true);
    const borders = pickerBorders(rounded);
    const resultsWidthChanged =
      state.layout.results.width !== layout.results.width;
    state.layout = layout;
    if (resultsWidthChanged) this.scheduleRender();

    await workspace.nvim.call("nvim_win_set_config", [
      state.promptWindow,
      floatConfig(layout.prompt, borders.prompt, {
        title: ` ${this.name ?? ""} `,
        title_pos: "left",
      }),
    ]);
    await workspace.nvim.call("nvim_win_set_config", [
      state.resultsWindow,
      floatConfig(layout.results, borders.results, { focusable: false }),
    ]);

    if (!layout.preview) return;

    const title = previewPath ? ` ${path.basename(previewPath)} ` : " preview ";
    if (state.preview) {
      await workspace.nvim.call("nvim_win_set_config", [
        state.preview.window,
        floatConfig(layout.preview, borders.preview, {
          focusable: false,
          title,
          title_pos: "left",
        }),
      ]);
      return;
    }

    const buffer = (await workspace.nvim.call("nvim_create_buf", [
      false,
      true,
    ])) as number;
    await this.configurePreviewBuffer(buffer);
    const previewWindow = (await workspace.nvim.call("nvim_open_win", [
      buffer,
      false,
      floatConfig(layout.preview, borders.preview, {
        focusable: false,
        title,
        title_pos: "left",
      }),
    ])) as number;
    await workspace.nvim.call("nvim_win_set_option", [
      previewWindow,
      "winhighlight",
      "NormalFloat:NormalFloat,FloatBorder:CocUiPickerBorder,FloatTitle:CocUiPickerBorder",
    ]);
    await workspace.nvim.call("nvim_win_set_option", [
      previewWindow,
      "wrap",
      false,
    ]);
    await workspace.nvim.call("nvim_win_set_option", [
      previewWindow,
      "cursorline",
      false,
    ]);
    state.preview = {
      buffer,
      window: previewWindow,
      path: previewPath ?? "",
      identity: "",
    };
  }

  private async configurePreviewBuffer(buffer: number): Promise<void> {
    await workspace.nvim.call("nvim_buf_set_option", [buffer, "buftype", "nofile"]);
    await workspace.nvim.call("nvim_buf_set_option", [buffer, "bufhidden", "wipe"]);
    await workspace.nvim.call("nvim_buf_set_option", [buffer, "swapfile", false]);
    await workspace.nvim.call("nvim_buf_set_option", [buffer, "modifiable", false]);
    await workspace.nvim.call("nvim_buf_set_option", [buffer, "readonly", true]);
    await workspace.nvim.call("nvim_buf_set_option", [buffer, "undolevels", -1]);
  }

  private async writePreviewBuffer(
    buffer: number,
    lines: string[],
    filetype: string,
  ): Promise<void> {
    await workspace.nvim.pauseNotification();
    workspace.nvim.call("nvim_buf_set_option", [buffer, "modifiable", true], true);
    workspace.nvim.call("nvim_buf_set_option", [buffer, "readonly", false], true);
    workspace.nvim.call(
      "nvim_buf_set_lines",
      [buffer, 0, -1, false, lines.length ? lines : [""]],
      true,
    );
    workspace.nvim.call("nvim_buf_set_option", [buffer, "modifiable", false], true);
    workspace.nvim.call("nvim_buf_set_option", [buffer, "readonly", true], true);
    // Always set filetype (including "") so a prior ft does not leak across items.
    workspace.nvim.call("nvim_buf_set_option", [buffer, "filetype", filetype], true);
    await workspace.nvim.resumeNotification(false);
  }

  private async detectFiletype(filePath: string): Promise<string | undefined> {
    try {
      const detected = (await workspace.nvim.lua(
        `return vim.filetype.match({ filename = ... })`,
        [filePath],
      )) as unknown;
      return typeof detected === "string" && detected ? detected : undefined;
    } catch {
      return undefined;
    }
  }

  private async focusPreviewLine(
    preview: PreviewState,
    focusLine: number | undefined,
    lineCount: number,
  ): Promise<void> {
    const state = this.state;
    if (!state) return;
    await workspace.nvim.call("nvim_buf_clear_namespace", [
      preview.buffer,
      state.namespace,
      0,
      -1,
    ]);
    if (!focusLine || lineCount < 1) return;
    const line = Math.max(1, Math.min(focusLine, lineCount));
    await workspace.nvim.call("nvim_buf_add_highlight", [
      preview.buffer,
      state.namespace,
      "PmenuSel",
      line - 1,
      0,
      -1,
    ]);
    await workspace.nvim.lua(
      `
      local win, line = ...
      if vim.api.nvim_win_is_valid(win) then
        vim.api.nvim_win_call(win, function()
          vim.api.nvim_win_set_cursor(win, { line, 0 })
          vim.cmd('normal! zz')
        end)
      end
      `,
      [preview.window, line],
    );
  }

  private context(input: string): ListContext {
    const state = this.state;
    if (!state) throw new Error("Picker is not visible");
    const options: ListOptions = {
      position: "float",
      reverse: false,
      input,
      ignorecase: true,
      interactive: this.source?.interactive ?? false,
      sort: false,
      mode: "insert",
      matcher: "fuzzy",
      autoPreview: false,
      numberSelect: false,
      noQuit: false,
      first: false,
    };
    return {
      args: this.args,
      input,
      cwd: workspace.cwd,
      options,
      window: workspace.nvim.createWindow(state.targetWindow),
      buffer: workspace.nvim.createBuffer(state.targetBuffer),
      listWindow: workspace.nvim.createWindow(state.resultsWindow),
    };
  }

  private async openWindows(name: string): Promise<FloatState> {
    const targetWindow = (await workspace.nvim.call("win_getid")) as number;
    const targetBuffer = (await workspace.nvim.call("bufnr", ["%"])) as number;
    const targetMode = (await workspace.nvim.call("mode", [1])) as string;
    await this.configureHighlights();
    const columns = (await workspace.nvim.getOption("columns")) as number;
    const lines = (await workspace.nvim.getOption("lines")) as number;
    const layout = computePickerLayout({
      columns,
      lines,
      showPreview: false,
      minColumns: this.previewMinColumns,
    });
    const namespace = (await workspace.nvim.call("nvim_create_namespace", [
      "coc-ui-picker",
    ])) as number;
    const promptBuffer = (await workspace.nvim.call("nvim_create_buf", [false, true])) as number;
    const resultsBuffer = (await workspace.nvim.call("nvim_create_buf", [false, true])) as number;
    const borders = pickerBorders(
      workspace.getConfiguration("dialog").get<boolean>("rounded", true),
    );
    const promptWindow = (await workspace.nvim.call("nvim_open_win", [
      promptBuffer,
      true,
      floatConfig(layout.prompt, borders.prompt, {
        title: ` ${name} `,
        title_pos: "left",
      }),
    ])) as number;
    const resultsWindow = (await workspace.nvim.call("nvim_open_win", [
      resultsBuffer,
      false,
      floatConfig(layout.results, borders.results, { focusable: false }),
    ])) as number;
    for (const buffer of [promptBuffer, resultsBuffer]) {
      await workspace.nvim.call("nvim_buf_set_option", [buffer, "buftype", "nofile"]);
      await workspace.nvim.call("nvim_buf_set_option", [buffer, "bufhidden", "wipe"]);
      await workspace.nvim.call("nvim_buf_set_option", [buffer, "swapfile", false]);
    }
    await workspace.nvim.call("nvim_buf_set_option", [promptBuffer, "filetype", "cocui-picker-prompt"]);
    await workspace.nvim.call("nvim_buf_set_option", [resultsBuffer, "filetype", "cocui-picker"]);
    await workspace.nvim.call("nvim_win_set_option", [
      promptWindow,
      "winhighlight",
      "NormalFloat:NormalFloat,FloatBorder:CocUiPickerBorder,FloatTitle:CocUiPickerBorder",
    ]);
    await workspace.nvim.call("nvim_win_set_option", [
      promptWindow,
      "wrap",
      false,
    ]);
    await workspace.nvim.call("nvim_win_set_option", [resultsWindow, "cursorline", false]);
    await workspace.nvim.call("nvim_win_set_option", [resultsWindow, "wrap", false]);
    await workspace.nvim.call("nvim_win_set_option", [
      resultsWindow,
      "winhighlight",
      "NormalFloat:NormalFloat,FloatBorder:CocUiPickerBorder,FloatTitle:CocUiPickerBorder",
    ]);
    return {
      namespace,
      promptBuffer,
      promptWindow,
      resultsBuffer,
      resultsWindow,
      targetBuffer,
      targetMode,
      targetWindow,
      layout,
    };
  }

  private async configureHighlights(): Promise<void> {
    const normal = (await workspace.nvim.call("nvim_get_hl", [
      0,
      { name: "NormalFloat", link: false },
    ])) as Record<string, unknown>;
    const border = (await workspace.nvim.call("nvim_get_hl", [
      0,
      { name: "FloatBorder", link: false },
    ])) as Record<string, unknown>;
    const pickerBorder = { ...border };
    for (const key of ["bg", "ctermbg", "blend"]) {
      if (normal[key] == null) delete pickerBorder[key];
      else pickerBorder[key] = normal[key];
    }
    await workspace.nvim.call("nvim_set_hl", [
      0,
      "CocUiPickerBorder",
      pickerBorder,
    ]);
  }

  private installCommands(): void {
    const state = this.state;
    if (!state) return;
    const mappings: Array<[string, string]> = [
      ["<Esc>", "ui.picker.close"],
      ["<C-c>", "ui.picker.close"],
      ["<Tab>", "ui.picker.actions"],
      ["<CR>", "ui.picker.accept"],
      ["<C-n>", "ui.picker.next"],
      ["<Down>", "ui.picker.next"],
      ["<C-p>", "ui.picker.previous"],
      ["<Up>", "ui.picker.previous"],
    ];
    for (const [key, command] of mappings) {
      void workspace.nvim.call("nvim_buf_set_keymap", [state.promptBuffer, "i", key, `<Cmd>CocCommand ${command}<CR>`, { noremap: true, silent: true, nowait: true }]);
    }
  }
}

/** Floor so a misconfigured minColumns cannot collapse the threshold to zero. */
const LAYOUT_MIN_COLUMNS_FLOOR = 40;

let activePicker: ListPicker | undefined;

export function registerPickerCommands(picker: ListPicker): Disposable[] {
  activePicker = picker;
  return [
    commands.registerCommand("ui.picker.close", () => activePicker?.close()),
    commands.registerCommand("ui.picker.resume", () => activePicker?.resume()),
    commands.registerCommand("ui.picker.actions", () =>
      activePicker?.showActions(),
    ),
    commands.registerCommand("ui.picker.accept", () => activePicker?.accept()),
    commands.registerCommand("ui.picker.next", () => activePicker?.move(1)),
    commands.registerCommand("ui.picker.previous", () => activePicker?.move(-1)),
  ];
}
